"use client";
import {
  Children,
  cloneElement,
  isValidElement,
  useEffect,
  useId,
  useRef,
  useState,
  type ReactElement,
  type ReactNode,
} from "react";
import { pastelColour } from "../primitives/gradient";
import { reducedMotionNow } from "../hooks/reduced-motion";
import { towardsTrigger, useFloating } from "../hooks/anchor";

export interface TooltipProps {
  /** What the tooltip says. Keep it short: a label or a shortcut. */
  content: ReactNode;
  /** The element it describes. A single element gets `aria-describedby` directly. */
  children: ReactNode;
  /** Which side of the trigger it sits on. Default: "top" */
  side?: "top" | "bottom";
  /** Hover delay before it appears, in ms. Keyboard focus shows it at once. Default: 300 */
  delay?: number;
  className?: string;
}

/**
 * A tooltip that stays put. It sits centred on its trigger, appears after a
 * short hover or straight away on keyboard focus, and closes on Escape. Its
 * border takes the Prism colour of where the trigger sits on the page, so it
 * belongs to the same light system without following the cursor around.
 *
 * It shares the overlay engine with Popover and Menu: it sits in the top
 * layer, so an overflow: hidden card cannot clip it, flips below when there
 * is no room above, and springs in. Its text is always in the page, hidden,
 * so the description is there the moment the trigger takes focus.
 *
 * @example
 * <Tooltip content="Undo (⌘Z)">
 *   <IconButton aria-label="Undo"><Undo2 size={15} /></IconButton>
 * </Tooltip>
 */
export const Tooltip = ({ content, children, side = "top", delay = 300, className = "" }: TooltipProps) => {
  const id = useId();
  const wrapRef = useRef<HTMLSpanElement>(null);
  const tipRef = useRef<HTMLSpanElement>(null);
  const timer = useRef<number | undefined>(undefined);
  const [open, setOpen] = useState(false);
  const [tint, setTint] = useState("255 255 255");

  useFloating({
    open,
    triggerRef: wrapRef,
    floatingRef: tipRef,
    side,
    align: "center",
    offset: 8,
    render: (p, landed) => {
      const el = tipRef.current;
      if (!el) return;
      const [, dy] = towardsTrigger(landed);
      el.style.opacity = Math.min(1, Math.max(0, p)).toFixed(3);
      el.style.transform = reducedMotionNow() ? "none" : `translateY(${(dy * (1 - p) * 3).toFixed(2)}px)`;
    },
  });

  const show = (immediate: boolean) => {
    window.clearTimeout(timer.current);
    const rect = wrapRef.current?.getBoundingClientRect();
    if (rect) {
      const c = pastelColour(((rect.left + rect.width / 2) / window.innerWidth) * 100, ((rect.top + rect.height / 2) / window.innerHeight) * 100, 0);
      setTint(`${c.r} ${c.g} ${c.b}`);
    }
    if (immediate) setOpen(true);
    else timer.current = window.setTimeout(() => setOpen(true), delay);
  };
  const hide = () => {
    window.clearTimeout(timer.current);
    setOpen(false);
  };

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") hide();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open]);

  useEffect(() => () => window.clearTimeout(timer.current), []);

  const only = Children.count(children) === 1 && isValidElement(children) ? (children as ReactElement<{ "aria-describedby"?: string }>) : null;
  const trigger = only
    ? cloneElement(only, {
        "aria-describedby": [only.props["aria-describedby"], id].filter(Boolean).join(" "),
      })
    : children;

  return (
    <span
      ref={wrapRef}
      className={`relative inline-flex ${className}`}
      onPointerEnter={(e) => e.pointerType === "mouse" && show(false)}
      onPointerLeave={hide}
      onFocus={(e) => (e.target as HTMLElement).matches(":focus-visible") && show(true)}
      onBlur={hide}
      aria-describedby={only ? undefined : id}
    >
      {trigger}
      <span
        ref={tipRef}
        id={id}
        role="tooltip"
        popover="manual"
        className="pointer-events-none m-0 overflow-visible whitespace-nowrap rounded-lg border bg-[#0b0b0b]/95 px-2.5 py-1.5 text-xs text-white/85 shadow-[0_8px_24px_rgba(0,0,0,0.5)] backdrop-blur"
        style={{ borderColor: `rgb(${tint} / 0.35)` }}
      >
        {content}
      </span>
    </span>
  );
};

"use client";
import { useId, useLayoutEffect, useRef, useSyncExternalStore, type RefObject } from "react";
import { SPRINGS, useDismissLayer, usePresence, type DismissReason } from "./overlay";

/**
 * Attach a floating element to a trigger.
 *
 * The element goes in the top layer (`popover="manual"`), so no overflow,
 * transform or z-index on any ancestor can clip it or bury it. Then it is
 * placed one of two ways, chosen by feature detection:
 *
 * - CSS anchor positioning, where the browser has it: `position-area` puts it
 *   beside the trigger and `position-try-fallbacks` flips it when there is no
 *   room. Scrolling costs no JavaScript at all; the loop only reads which side
 *   it landed on, so the spring can come from the right direction.
 * - Otherwise JavaScript measures the trigger each frame, flips to the
 *   opposite side if it would overflow, and shifts it to stay in the viewport.
 */

export type Side = "top" | "bottom" | "left" | "right";
export type Align = "start" | "center" | "end";
/** "auto" uses CSS anchor positioning when the browser supports it. "js" always measures. */
export type Positioning = "auto" | "js";
export type Strategy = "anchor" | "js";

export const anchorPositioningSupported = (): boolean =>
  typeof CSS !== "undefined" && CSS.supports("anchor-name: --a") && CSS.supports("position-try-fallbacks: flip-block");

const noop = () => () => {};
/** Whether this browser has CSS anchor positioning. False on the server, so first paint matches. */
export const useAnchorSupport = () => useSyncExternalStore(noop, anchorPositioningSupported, () => false);

const OPPOSITE: Record<Side, Side> = { top: "bottom", bottom: "top", left: "right", right: "left" };
const clamp = (v: number, lo: number, hi: number) => Math.min(Math.max(v, lo), Math.max(lo, hi));
const isVertical = (side: Side) => side === "top" || side === "bottom";

/** Where a floating box of `size` goes beside `anchor`: flipped if it does not fit, shifted to stay `pad` inside the viewport. */
export const computePlacement = (
  anchor: DOMRect,
  size: { width: number; height: number },
  side: Side,
  align: Align,
  offset: number,
  pad = 8
) => {
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const room: Record<Side, number> = {
    bottom: vh - anchor.bottom - offset - pad,
    top: anchor.top - offset - pad,
    right: vw - anchor.right - offset - pad,
    left: anchor.left - offset - pad,
  };
  const need = isVertical(side) ? size.height : size.width;
  const resolved = room[side] < need && room[OPPOSITE[side]] > room[side] ? OPPOSITE[side] : side;

  const along = (start: number, length: number, extent: number) =>
    align === "start" ? start : align === "end" ? start + length - extent : start + length / 2 - extent / 2;

  if (isVertical(resolved)) {
    const y = resolved === "bottom" ? anchor.bottom + offset : anchor.top - offset - size.height;
    const x = clamp(along(anchor.left, anchor.width, size.width), pad, vw - pad - size.width);
    return { x, y, side: resolved };
  }
  const x = resolved === "right" ? anchor.right + offset : anchor.left - offset - size.width;
  const y = clamp(along(anchor.top, anchor.height, size.height), pad, vh - pad - size.height);
  return { x, y, side: resolved };
};

const positionArea = (side: Side, align: Align) => {
  if (align === "center") return side;
  if (isVertical(side)) return `${side} ${align === "start" ? "span-right" : "span-left"}`;
  return `${side} ${align === "start" ? "span-bottom" : "span-top"}`;
};

const MARGIN: Record<Side, string> = { bottom: "margin-top", top: "margin-bottom", right: "margin-left", left: "margin-right" };

/** Which side the browser actually put it on, read from where it ended up. */
const landedOn = (anchor: DOMRect, float: DOMRect, side: Side): Side =>
  isVertical(side)
    ? float.top + float.height / 2 > anchor.top + anchor.height / 2
      ? "bottom"
      : "top"
    : float.left + float.width / 2 > anchor.left + anchor.width / 2
      ? "right"
      : "left";

/** CSS transform-origin for a panel that grows out of its trigger. */
export const originFor = (side: Side, align: Align) => {
  const cross = align === "start" ? "0%" : align === "end" ? "100%" : "50%";
  switch (side) {
    case "bottom":
      return `${cross} 0%`;
    case "top":
      return `${cross} 100%`;
    case "right":
      return `0% ${cross}`;
    case "left":
      return `100% ${cross}`;
  }
};

/** Unit vector pointing from the panel back towards its trigger, for the entrance offset. */
export const towardsTrigger = (side: Side) =>
  ({ bottom: [0, -1], top: [0, 1], right: [-1, 0], left: [1, 0] })[side] as [number, number];

export interface FloatingOptions {
  open: boolean;
  /** The element it is attached to. */
  triggerRef: RefObject<HTMLElement | null>;
  /** The floating element. Render it with `popover="manual"`. */
  floatingRef: RefObject<HTMLElement | null>;
  side?: Side;
  align?: Align;
  /** Gap from the trigger in px. */
  offset?: number;
  positioning?: Positioning;
  /** Put it on the dismiss stack (Escape, click outside). Leave out for tooltips. */
  onDismiss?: (reason: DismissReason) => void;
  /** Called every frame while it moves, with spring progress 0..1 and the side it is on. */
  render: (p: number, side: Side) => void;
}

/** Presence, top layer, placement and dismissal for anything attached to a trigger. */
export const useFloating = ({
  open,
  triggerRef,
  floatingRef,
  side = "bottom",
  align = "start",
  offset = 6,
  positioning = "auto",
  onDismiss,
  render,
}: FloatingOptions) => {
  const sideRef = useRef<Side>(side);
  const presence = usePresence(open, (p) => render(p, sideRef.current), SPRINGS.panel);
  const { mounted } = presence;
  const name = `--prism-${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const supported = useAnchorSupport();
  const strategy: Strategy = positioning === "auto" && supported ? "anchor" : "js";

  useLayoutEffect(() => {
    const trigger = triggerRef.current;
    const el = floatingRef.current;
    if (!mounted || !trigger || !el) return;
    const s = el.style;
    s.position = "fixed";
    s.inset = "auto";
    s.margin = "0";
    if (strategy === "anchor") {
      trigger.style.setProperty("anchor-name", name);
      s.setProperty("position-anchor", name);
      s.setProperty("position-area", positionArea(side, align));
      s.setProperty(
        "position-try-fallbacks",
        isVertical(side) ? "flip-block, flip-inline, flip-block flip-inline" : "flip-inline, flip-block, flip-inline flip-block"
      );
      s.setProperty(MARGIN[side], `${offset}px`);
    }
    try {
      if (!el.matches(":popover-open")) el.showPopover();
    } catch {
      // No Popover API: it still renders, fixed-position, just without the top layer.
    }

    let raf = 0;
    let last = "";
    const place = () => {
      const a = trigger.getBoundingClientRect();
      if (strategy === "anchor") {
        sideRef.current = landedOn(a, el.getBoundingClientRect(), side);
      } else {
        const p = computePlacement(a, { width: el.offsetWidth, height: el.offsetHeight }, side, align, offset);
        const key = `${Math.round(p.x * 2)},${Math.round(p.y * 2)}`;
        if (key !== last) {
          s.left = `${p.x}px`;
          s.top = `${p.y}px`;
          last = key;
        }
        sideRef.current = p.side;
      }
      raf = requestAnimationFrame(place);
    };
    place();

    return () => {
      cancelAnimationFrame(raf);
      trigger.style.removeProperty("anchor-name");
      for (const prop of ["position-anchor", "position-area", "position-try-fallbacks", "left", "top", ...Object.values(MARGIN)]) {
        s.removeProperty(prop);
      }
      try {
        el.hidePopover();
      } catch {
        // Already hidden or unsupported.
      }
    };
  }, [mounted, strategy, side, align, offset, name, triggerRef, floatingRef]);

  useDismissLayer(
    open && !!onDismiss,
    (node) => !!floatingRef.current?.contains(node) || !!triggerRef.current?.contains(node),
    (reason) => onDismiss?.(reason)
  );

  return { ...presence, strategy, sideRef };
};

"use client";
import { useCallback, useEffect, useLayoutEffect, useRef, useState, type RefObject } from "react";

/**
 * The overlay layer: what every popover, menu, dialog, sheet and toast shares.
 *
 * - Springs that are integrated against real time, so a 120Hz screen moves
 *   them at the same speed as a 60Hz one.
 * - Presence: an overlay stays mounted until its exit spring has finished,
 *   then unmounts. Closing is never a cut.
 * - One dismiss stack: Escape closes the top layer only, and a click outside
 *   closes every layer that does not hold it, from the top down.
 * - Scroll lock and focus return for modals.
 *
 * Why not the browser's light dismiss? `popover="auto"` and `<dialog>` close
 * instantly, which leaves no room for an exit spring. So overlays use
 * `popover="manual"` for the top layer and do the dismissing here.
 */

// --- Springs ---------------------------------------------------------------

export type Spring = { k: number; d: number };
export type SpringState = { x: number; v: number };

/** The same constants the command palette and select use, so every overlay feels like one family. */
export const SPRINGS = {
  panel: { k: 200, d: 24 },
  indicator: { k: 180, d: 22 },
  stack: { k: 220, d: 26 },
} as const satisfies Record<string, Spring>;

/** Advance a spring by `dt` seconds, in fixed 1/120s substeps (semi-implicit Euler). */
export const stepSpring = (s: SpringState, target: number, { k, d }: Spring, dt: number) => {
  let left = Math.min(Math.max(dt, 0), 0.064); // a long pause (tab switch) does not fling it
  while (left > 0) {
    const h = Math.min(left, 1 / 120);
    s.v += (k * (target - s.x) - d * s.v) * h;
    s.x += s.v * h;
    left -= h;
  }
};

export const atRest = (s: SpringState, target: number, eps = 0.0005) =>
  Math.abs(target - s.x) < eps && Math.abs(s.v) < eps * 20;

// --- Presence --------------------------------------------------------------

/**
 * Keep something mounted while it animates out.
 *
 * `render(p)` is called every frame with progress from 0 (gone) to 1 (fully
 * present) and should write styles straight to the DOM, so nothing re-renders
 * per frame. Reversing mid-flight carries the velocity over.
 *
 * Returns `drive` and `kick` so a drag can move the progress by hand and
 * hand it back to the spring on release.
 */
export const usePresence = (open: boolean, render: (p: number) => void, spring: Spring = SPRINGS.panel) => {
  const [mounted, setMounted] = useState(open);
  if (open && !mounted) setMounted(true);

  const state = useRef<SpringState>({ x: 0, v: 0 });
  const raf = useRef(0);
  const openRef = useRef(open);
  const renderRef = useRef(render);
  useLayoutEffect(() => {
    renderRef.current = render;
    openRef.current = open;
  });

  const kick = useCallback(() => {
    if (raf.current) return;
    let last = performance.now();
    const tick = (now: number) => {
      const target = openRef.current ? 1 : 0;
      stepSpring(state.current, target, spring, (now - last) / 1000);
      last = now;
      // Leaving is done once it is invisible; there is no need to wait out the tail.
      const done = target === 1 ? atRest(state.current, 1) : state.current.x <= 0.01;
      if (done) state.current = { x: target, v: 0 };
      renderRef.current(state.current.x);
      if (done) {
        raf.current = 0;
        if (!openRef.current) setMounted(false);
        return;
      }
      raf.current = requestAnimationFrame(tick);
    };
    raf.current = requestAnimationFrame(tick);
  }, [spring]);

  useLayoutEffect(() => {
    if (!mounted) return;
    renderRef.current(state.current.x); // first frame before paint, so it never flashes in at full size
    kick();
  }, [open, mounted, kick]);

  useEffect(
    () => () => {
      cancelAnimationFrame(raf.current);
      raf.current = 0;
    },
    []
  );

  /** Set progress (and velocity, in progress per second) by hand. Call `kick` to let the spring carry on. */
  const drive = useCallback((x: number, v = 0) => {
    state.current = { x, v };
  }, []);

  return { mounted, drive, kick };
};

// --- Dismiss stack ---------------------------------------------------------

export type DismissReason = "escape" | "outside" | "focus-out" | "select" | "button";

type Layer = { contains: (node: Node) => boolean; dismiss: (reason: DismissReason) => void };

const layers: Layer[] = [];

const onKeyDown = (e: KeyboardEvent) => {
  if (e.key !== "Escape" || e.isComposing) return;
  const top = layers[layers.length - 1];
  if (!top) return;
  // Default-prevented, so a native dialog underneath does not also close.
  e.preventDefault();
  e.stopPropagation();
  top.dismiss("escape");
};

const onPointerDown = (e: PointerEvent) => {
  const target = e.target;
  if (!(target instanceof Node)) return;
  for (const layer of [...layers].reverse()) {
    if (layer.contains(target)) break;
    layer.dismiss("outside");
  }
};

const listen = (on: boolean) => {
  if (on) {
    window.addEventListener("keydown", onKeyDown, true);
    window.addEventListener("pointerdown", onPointerDown, true);
  } else {
    window.removeEventListener("keydown", onKeyDown, true);
    window.removeEventListener("pointerdown", onPointerDown, true);
  }
};

/**
 * Put a layer on the dismiss stack while `active`. Layers opened later sit
 * above earlier ones, so a menu inside a dialog closes before the dialog does.
 */
export const useDismissLayer = (active: boolean, contains: (node: Node) => boolean, dismiss: (reason: DismissReason) => void) => {
  const live = useRef({ contains, dismiss });
  useLayoutEffect(() => {
    live.current = { contains, dismiss };
  });
  useEffect(() => {
    if (!active) return;
    const layer: Layer = {
      contains: (node) => live.current.contains(node),
      dismiss: (reason) => live.current.dismiss(reason),
    };
    layers.push(layer);
    if (layers.length === 1) listen(true);
    return () => {
      const i = layers.indexOf(layer);
      if (i >= 0) layers.splice(i, 1);
      if (layers.length === 0) listen(false);
    };
  }, [active]);
};

// --- Focus -----------------------------------------------------------------

const FOCUSABLE =
  'a[href], button:not([disabled]), input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"]), [contenteditable="true"]';

export const focusablesIn = (root: Element | null): HTMLElement[] =>
  root ? [...root.querySelectorAll<HTMLElement>(FOCUSABLE)].filter((el) => el.getClientRects().length > 0) : [];

/** Focus `[data-autofocus]` if there is one, else the first focusable, else the root itself. */
export const focusInitial = (root: HTMLElement | null) => {
  if (!root) return;
  const el = root.querySelector<HTMLElement>("[data-autofocus]") ?? focusablesIn(root)[0] ?? root;
  el.focus({ preventScroll: true });
};

// --- Scroll lock -----------------------------------------------------------

let locks = 0;
let saved = { overflow: "", paddingRight: "" };

/** Stop the page scrolling behind a modal, without the layout jumping when the scrollbar goes. Nested locks count. */
export const lockScroll = () => {
  const html = document.documentElement;
  if (locks++ === 0) {
    const gap = window.innerWidth - html.clientWidth;
    saved = { overflow: html.style.overflow, paddingRight: html.style.paddingRight };
    html.style.overflow = "hidden";
    if (gap > 0) html.style.paddingRight = `${gap}px`;
  }
  let released = false;
  return () => {
    if (released) return;
    released = true;
    if (--locks === 0) {
      html.style.overflow = saved.overflow;
      html.style.paddingRight = saved.paddingRight;
    }
  };
};

// --- Modal -----------------------------------------------------------------

export interface ModalOptions {
  open: boolean;
  onDismiss: (reason: DismissReason) => void;
  dialogRef: RefObject<HTMLDialogElement | null>;
  /** The visible panel. A press anywhere else (the backdrop) is outside. */
  panelRef: RefObject<HTMLElement | null>;
  /** Whether a press on the backdrop dismisses. Off for confirmations. */
  dismissOnOutside?: boolean;
  render: (p: number) => void;
}

/**
 * A native `<dialog>` opened with showModal(), so the browser makes the rest
 * of the page inert and puts it in the top layer, with a spring on both ways.
 *
 * Focus moves to `[data-autofocus]` (or the first control) on open and back to
 * whatever opened it once it has gone.
 */
export const useModal = ({ open, onDismiss, dialogRef, panelRef, dismissOnOutside = true, render }: ModalOptions) => {
  const presence = usePresence(open, render);
  const { mounted } = presence;
  const onDismissRef = useRef(onDismiss);
  useLayoutEffect(() => {
    onDismissRef.current = onDismiss;
  });

  useLayoutEffect(() => {
    const dialog = dialogRef.current;
    if (!mounted || !dialog) return;
    const invoker = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    const release = lockScroll();
    if (!dialog.open) dialog.showModal();
    focusInitial(panelRef.current);
    return () => {
      release();
      if (dialog.open) dialog.close();
      if (invoker?.isConnected) invoker.focus({ preventScroll: true });
    };
  }, [mounted, dialogRef, panelRef]);

  // The browser can still ask to close (Android back, a close watcher): route it through the spring.
  useEffect(() => {
    const dialog = dialogRef.current;
    if (!mounted || !dialog) return;
    const onCancel = (e: Event) => {
      e.preventDefault();
      onDismissRef.current("escape");
    };
    dialog.addEventListener("cancel", onCancel);
    return () => dialog.removeEventListener("cancel", onCancel);
  }, [mounted, dialogRef]);

  useDismissLayer(
    open,
    (node) => !!panelRef.current?.contains(node) || !dismissOnOutside,
    onDismiss
  );

  return presence;
};

"use client";
import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

let query: MediaQueryList | null = null;
const getQuery = () => {
  if (!query && typeof window !== "undefined") query = window.matchMedia(QUERY);
  return query;
};

/**
 * A simulated setting, used by X-ray mode so anyone can see what every
 * component does with reduced motion without changing their OS setting.
 * null means "follow the system".
 */
let simulated: boolean | null = null;
const simulationListeners = new Set<() => void>();

/** Override the system setting (true or false), or pass null to follow it again. */
export const simulateReducedMotion = (value: boolean | null) => {
  if (simulated === value) return;
  simulated = value;
  simulationListeners.forEach((notify) => notify());
};

/** Whether the reduced-motion setting is currently simulated rather than read from the system. */
export const reducedMotionSimulated = (): boolean => simulated !== null;

/**
 * Whether the user has asked for reduced motion, read live. Cheap enough to
 * call every frame inside a rAF loop, so the setting takes effect mid-animation.
 */
export const reducedMotionNow = (): boolean => simulated ?? getQuery()?.matches ?? false;

/**
 * Seconds to feed into time-based colour drift (`pastelColour`, `colourField`).
 * With reduced motion the clock stops, so colour still follows the user but no
 * longer drifts on its own.
 */
export const motionTime = (): number => (reducedMotionNow() ? 0 : performance.now() / 1000);

const subscribe = (notify: () => void) => {
  const q = getQuery();
  q?.addEventListener("change", notify);
  simulationListeners.add(notify);
  return () => {
    q?.removeEventListener("change", notify);
    simulationListeners.delete(notify);
  };
};

/** React hook for the same setting. The server snapshot is false, so first paint matches. */
export const useReducedMotion = (): boolean =>
  useSyncExternalStore(subscribe, reducedMotionNow, () => false);

// Cursor-reactive radial gradient system
// Extracted from sammii.dev portfolio — this is the core visual identity

/**
 * 4-blob ambient gradient that responds to cursor position and time.
 * Returns a CSS background value with layered radial gradients.
 */
export const colourField = (xPc: number, yPc: number, t: number = 0, opacity: number = 15) => {
  const c = (n: number) => Math.min(255, Math.floor((255 / 100) * Math.max(0, Math.min(100, n))));

  // Cursor-driven base colours
  const r1 = c(xPc + Math.sin(t * 0.41) * 20);
  const g1 = c(yPc + Math.cos(t * 0.33) * 18);
  const b1 = 255 - c(xPc);

  const r2 = 255 - c(xPc + Math.cos(t * 0.37) * 18);
  const g2 = c(yPc + Math.sin(t * 0.29) * 15);
  const b2 = c(xPc);

  const r3 = c(yPc + Math.sin(t * 0.43) * 20);
  const g3 = c(xPc + Math.cos(t * 0.31) * 16);
  const b3 = 255 - c(yPc);

  const r4 = c(100 - xPc + Math.sin(t * 0.22) * 25);
  const g4 = c(100 - yPc + Math.cos(t * 0.18) * 20);
  const b4 = c(xPc + Math.sin(t * 0.27) * 20);

  // Radial positions oscillate
  const x1 = (50 + Math.sin(t * 0.31) * 16).toFixed(1);
  const y1 = (0 + Math.abs(Math.sin(t * 0.23)) * 22).toFixed(1);
  const x2 = (8 + Math.cos(t * 0.41) * 12).toFixed(1);
  const y2 = (75 + Math.sin(t * 0.29) * 10).toFixed(1);
  const x3 = (92 + Math.sin(t * 0.37) * 12).toFixed(1);
  const y3 = (75 + Math.cos(t * 0.43) * 10).toFixed(1);
  const x4 = (50 + Math.cos(t * 0.19) * 32).toFixed(1);
  const y4 = (50 + Math.sin(t * 0.27) * 28).toFixed(1);

  const op4 = Math.round(opacity * 0.73);

  return {
    background: `
      radial-gradient(ellipse at ${x1}% ${y1}%, rgb(${r1} ${g1} ${b1} / ${opacity}%), transparent 65%),
      radial-gradient(ellipse at ${x2}% ${y2}%, rgb(${r2} ${g2} ${b2} / ${opacity}%), transparent 65%),
      radial-gradient(ellipse at ${x3}% ${y3}%, rgb(${r3} ${g3} ${b3} / ${opacity}%), transparent 65%),
      radial-gradient(ellipse at ${x4}% ${y4}%, rgb(${r4} ${g4} ${b4} / ${op4}%), transparent 55%)
    `.trim(),
  };
};

/**
 * 3-circle colour blend driven by cursor position.
 * More vivid than colourField — good for hero elements.
 */
export const colourBlend = (xPc: number, yPc: number, opacity: number = 70) => {
  const c = (n: number) => {
    const colour = Math.floor((255 / 100) * n);
    return colour < 255 ? colour : 255;
  };

  const c1 = c(xPc);
  const c2 = c(yPc);
  const c3 = 255 - c(xPc);

  return {
    background: `radial-gradient(
        circle at 50% 0,
        rgb(${c1} ${c3} ${c2} / ${opacity}%),
        rgb(${c1} ${c3} ${c2} / 0%) 70.71%
      ),
      radial-gradient(
        circle at 6.7% 75%,
        rgb(${c3} ${c2} ${c1} / ${opacity}%),
        rgb(${c3} ${c2} ${c1} / 0%) 70.71%
      ),
      radial-gradient(
        circle at 93.3% 75%,
        rgb(${c2} ${c1} ${c3} / ${opacity}%),
        rgb(${c2} ${c1} ${c3} / 0%) 70.71%
      ) lavender`,
  };
};

/**
 * Compute a single RGB colour from cursor position.
 * Same formula used by the cursor follower and logo.
 */
export const cursorColour = (xPc: number, yPc: number) => {
  const c = (n: number) => Math.min(255, Math.floor((255 / 100) * n));
  return { r: c(xPc), g: c(yPc), b: 255 - c(xPc) };
};

/**
 * Pastel variant — floors each channel at 140 so colours stay light.
 * Used by the card spotlight border system.
 */
export const pastelColour = (xPc: number, yPc: number, t: number = 0) => {
  const cv = (n: number) => 140 + Math.floor((115 / 100) * Math.max(0, Math.min(100, n)));
  const rPc = Math.max(0, Math.min(100, xPc + Math.sin(t * 1.1) * 28));
  const gPc = Math.max(0, Math.min(100, yPc + Math.cos(t * 0.7) * 22));
  const bPc = 100 - rPc;
  return { r: cv(rPc), g: cv(gPc), b: cv(bPc) };
};
